56	  Future<Either<Failure, List<Entry>>> search(
57	    String query, {
58	    EntrySource? source,
59	    DateTime? dateFrom,
60	    DateTime? dateTo,
61	  }) {
62	    searchCalls.add(query);
63	    searchFilterCalls.add(
64	      (source: source, dateFrom: dateFrom, dateTo: dateTo),
65	    );
66	    if (gated) {
67	      final completer = Completer<Either<Failure, List<Entry>>>();
68	      _completers.add(completer);
69	      return completer.future;
70	    }
71	    if (_results.isEmpty) {
72	      throw StateError(
73	        'no queued search() result for call #${searchCalls.length}',
74	      );
75	    }
76	    return Future.value(_results.removeAt(0));
77	  }
