100	/// Collects every state the cubit emits for the duration of [act] — same
101	/// helper/rationale `auth_cubit_test.dart` already documents: this stack
102	/// has no `bloc_test` pin, so this drives [EntriesSearchCubit] through its
103	/// public API only, the same way any other `flutter_bloc` consumer would.
104	Future<List<Resource<List<Entry>>>> _emittedDuring(
105	  EntriesSearchCubit cubit,
106	  FutureOr<void> Function() act,
107	) async {
108	  final emitted = <Resource<List<Entry>>>[];
109	  final subscription = cubit.stream.listen(emitted.add);
110	  await act();
111	  await subscription.cancel();
112	  return emitted;
113	}
